arguments.content:
/* Orchard Design System */
:root {
  /* Colors - OKLCH for perceptual uniformity */
  --brand-primary: oklch(55% 0.22 265);
  --brand-accent: oklch(75% 0.18 45);
  --text-primary: oklch(20% 0.02 265);
  --text-secondary: oklch(50% 0.02 265);
  --bg-surface: oklch(98% 0.01 265);
  --bg-elevated: oklch(100% 0 0);
  --border-subtle: oklch(90% 0.01 265);

  /* Product card gradients */
  --gradient-phone: linear-gradient(135deg, oklch(85% 0.08 300), oklch(80% 0.12 280));
  --gradient-laptop: linear-gradient(135deg, oklch(85% 0.06 220), oklch(80% 0.10 200));
  --gradient-tablet: linear-gradient(135deg, oklch(85% 0.08 180), oklch(80% 0.10 160));
  --gradient-audio: linear-gradient(135deg, oklch(85% 0.08 45), oklch(80% 0.10 30));
  --gradient-watch: linear-gradient(135deg, oklch(85% 0.06 300), oklch(80% 0.08 320));
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Helvetica Neue', sans-serif;
  background: #f5f5f7;
  color: #1d1d1f;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Typography Scale */
h1 { font-size: 56px; font-weight: 700; letter-spacing: -0.02em; }
h2 { font-size: 40px; font-weight: 700; letter-spacing: -0.02em; }
h3 { font-size: 28px; font-weight: 600; letter-spacing: -0.01em; }
h4 { font-size: 21px; font-weight: 600; }
p { font-size: 14px; color: #6e6e73; }

.subheadline {
  font-size: 28px;
  font-weight: 400;
  color: #6e6e73;
}

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid #d2d2d7;
}

.nav-inner {
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 22px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  font-size: 18px;
  font-weight: 600;
  color: #1d1d1f;
  text-decoration: none;
  letter-spacing: -0.01em;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  font-size: 12px;
  color: #1d1d1f;
  text-decoration: none;
  opacity: 0.8;
  transition: opacity 0.2s;
}

.nav-links a:hover {
  opacity: 1;
}

/* Ribbon Banner */
.ribbon-banner {
  background: #0071e3;
  color: white;
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
}

.ribbon-banner a {
  color: white;
  text-decoration: underline;
}

/* Hero Section */
.hero {
  background: white;
  padding: 80px 22px;
  text-align: center;
}

.hero h1 {
  margin-bottom: 8px;
}

.hero .subheadline {
  margin-bottom: 24px;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.2s;
  cursor: pointer;
  border: none;
}

.btn-primary {
  background: #0071e3;
  color: white;
}

.btn-primary:hover {
  background: #0077ed;
}

.btn-secondary {
  background: transparent;
  color: #0071e3;
  border: 1px solid #0071e3;
}

.btn-secondary:hover {
  background: #0071e3;
  color: white;
}

.btn-small {
  padding: 8px 16px;
  font-size: 12px;
}

/* Section styling */
.section {
  padding: 60px 22px;
  background: white;
}

.section-dark {
  background: #1d1d1f;
  color: white;
}

.section-gray {
  background: #f5f5f7;
}

.section-header {
  max-width: 1024px;
  margin: 0 auto 40px;
}

.section-header h2 {
  margin-bottom: 8px;
}

/* Product Grid (Homepage) */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 22px;
}

.product-tile {
  background: var(--gradient);
  border-radius: 18px;
  padding: 40px;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  position: relative;
  overflow: hidden;
}

.product-tile.phone { background: var(--gradient-phone); }
.product-tile.laptop { background: var(--gradient-laptop); }
.product-tile.tablet { background: var(--gradient-tablet); }
.product-tile.audio { background: var(--gradient-audio); }
.product-tile.watch { background: var(--gradient-watch); }

.product-tile img {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  max-width: 80%;
  max-height: 60%;
  object-fit: contain;
}

.product-tile-content {
  position: relative;
  z-index: 1;
}

.product-tile h3 {
  font-size: 28px;
  margin-bottom: 4px;
}

.product-tile p {
  font-size: 14px;
  margin-bottom: 16px;
  color: inherit;
  opacity: 0.8;
}

.product-tile .badge {
  display: inline-block;
  background: #0071e3;
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 980px;
  margin-bottom: 8px;
}

.product-tile .ctas {
  display: flex;
  gap: 12px;
}

.product-tile .ctas a {
  font-size: 14px;
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}

.product-tile .ctas a:hover {
  opacity: 0.7;
}

/* Carousel */
.carousel-container {
  position: relative;
  max-width: 1024px;
  margin: 0 auto;
}

.carousel-track-wrapper {
  overflow: hidden;
  margin: 0 40px;
}

.carousel-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 8px 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-card {
  flex: 0 0 280px;
  background: white;
  border-radius: 18px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.carousel-card img {
  width: 100%;
  height: 160px;
  object-fit: contain;
}

.carousel-card .badge {
  display: inline-block;
  background: #0071e3;
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 980px;
  width: fit-content;
}

.carousel-card h4 {
  font-size: 17px;
  font-weight: 600;
}

.carousel-card .tagline {
  font-size: 13px;
  color: #6e6e73;
}

.carousel-card .price {
  font-size: 14px;
  font-weight: 500;
  margin-top: auto;
}

.carousel-card .monthly {
  font-size: 12px;
  color: #6e6e73;
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: white;
  border: 1px solid #d2d2d7;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #1d1d1f;
  z-index: 10;
  transition: all 0.2s;
}

.carousel-nav:hover {
  background: #f5f5f7;
}

.carousel-nav.prev {
  left: 0;
}

.carousel-nav.next {
  right: 0;
}

.carousel-nav:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

/* Entertainment Tabs */
.entertainment-tabs {
  display: flex;
  gap: 4px;
  justify-content: center;
  margin-bottom: 40px;
}

.tab-btn {
  padding: 12px 24px;
  border: none;
  background: #f5f5f7;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  color: #1d1d1f;
}

.tab-btn.active {
  background: #1d1d1f;
  color: white;
}

.tab-btn:hover:not(.active) {
  background: #e8e8ed;
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

.entertainment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.entertainment-card {
  background: white;
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;
}

.entertainment-card img {
  width: 100%;
  height: 140px;
  object-fit: cover;
}

.entertainment-card-content {
  padding: 12px;
}

.entertainment-card h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
}

.entertainment-card p {
  font-size: 12px;
  margin-bottom: 8px;
}

.entertainment-card .cta {
  font-size: 12px;
  color: #0071e3;
  text-decoration: none;
}

/* Category Hero */
.category-hero {
  background: linear-gradient(180deg, #f5f5f7 0%, white 100%);
  padding: 60px 22px;
  text-align: center;
}

.category-hero h1 {
  font-size: 48px;
  margin-bottom: 8px;
}

/* Sticky Section Nav */
.section-nav {
  position: sticky;
  top: 44px;
  z-index: 50;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid #d2d2d7;
  overflow-x: auto;
}

.section-nav-inner {
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 32px;
  justify-content: center;
  min-width: max-content;
}

.section-nav a {
  padding: 16px 0;
  font-size: 13px;
  color: #6e6e73;
  text-decoration: none;
  border-bottom: 3px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
}

.section-nav a:hover,
.section-nav a.active {
  color: #1d1d1f;
  border-bottom-color: #0071e3;
}

/* Product Icon Bar */
.product-icon-bar {
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
  padding: 40px 22px;
  background: white;
}

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: #1d1d1f;
}

.product-icon-item img {
  width: 48px;
  height: 48px;
  object-fit: contain;
}

.product-icon-item span {
  font-size: 12px;
}

/* Quick Links */
.quick-links {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  padding: 40px 22px;
  background: white;
}

.quick-link {
  padding: 12px 24px;
  background: #f5f5f7;
  border-radius: 980px;
  font-size: 13px;
  font-weight: 500;
  color: #1d1d1f;
  text-decoration: none;
  transition: background 0.2s;
}

.quick-link:hover {
  background: #e8e8ed;
}

/* Help Cards */
.help-card {
  background: white;
  border-radius: 18px;
  padding: 32px;
  text-align: center;
}

.help-card h4 {
  font-size: 19px;
  margin-bottom: 8px;
}

.help-card p {
  font-size: 14px;
}

/* Difference Cards */
.difference-card {
  background: white;
  border-radius: 18px;
  padding: 24px;
  flex: 0 0 280px;
}

.difference-card h4 {
  font-size: 17px;
  margin-bottom: 8px;
}

.difference-card p {
  font-size: 13px;
}

/* Savings Cards */
.savings-card {
  background: white;
  border-radius: 18px;
  padding: 24px;
  flex: 0 0 280px;
}

.savings-card .badge {
  display: inline-block;
  background: #0071e3;
  color: white;
  font-size: 10px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 980px;
  margin-bottom: 12px;
}

.savings-card h4 {
  font-size: 17px;
  margin-bottom: 8px;
}

.savings-card p {
  font-size: 13px;
}

/* Guide Cards */
.guide-card {
  background: white;
  border-radius: 18px;
  padding: 24px;
  flex: 0 0 240px;
}

.guide-card h4 {
  font-size: 17px;
  margin-bottom: 8px;
}

.guide-card p {
  font-size: 13px;
}

/* Footer */
.footer {
  background: #f5f5f7;
  padding: 40px 22px 20px;
}

.footer-content {
  max-width: 1024px;
  margin: 0 auto;
}

.footer-accordion {
  display: none;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
}

.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 12px;
  color: #1d1d1f;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 8px;
}

.footer-col a {
  font-size: 12px;
  color: #6e6e73;
  text-decoration: none;
}

.footer-col a:hover {
  color: #1d1d1f;
}

.footer-legal {
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid #d2d2d7;
  font-size: 11px;
  color: #6e6e73;
}

/* Mobile Styles */
@media (max-width: 768px) {
  h1 { font-size: 36px; }
  h2 { font-size: 28px; }
  .subheadline { font-size: 20px; }

  .nav-links { display: none; }

  .product-grid {
    grid-template-columns: 1fr;
  }

  .product-tile {
    min-height: 320px;
    padding: 28px;
  }

  .entertainment-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .carousel-track-wrapper {
    margin: 0 16px;
  }

  .carousel-nav {
    width: 32px;
    height: 32px;
    font-size: 14px;
  }

  .footer-links {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .footer-accordion-item {
    border-bottom: 1px solid #d2d2d7;
  }

  .footer-accordion-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 0;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
  }

  .footer-accordion-header::after {
    content: '+';
    font-size: 20px;
    font-weight: 300;
  }

  .footer-accordion-item.open .footer-accordion-header::after {
    content: '−';
  }

  .footer-accordion-content {
    display: none;
    padding-bottom: 14px;
  }

  .footer-accordion-item.open .footer-accordion-content {
    display: block;
  }

  .footer-accordion-content a {
    display: block;
    font-size: 13px;
    color: #6e6e73;
    text-decoration: none;
    padding: 6px 0;
  }

  .section-nav {
    top: 44px;
  }

  .section-nav-inner {
    justify-content: flex-start;
    padding: 0 16px;
  }

  .section-nav a {
    font-size: 12px;
    padding: 12px 0;
  }

  .category-hero h1 {
    font-size: 32px;
  }
}

@media (max-width: 480px) {
  .hero {
    padding: 48px 16px;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .btn {
    width: 100%;
    max-width: 280px;
    text-align: center;
  }

  .entertainment-grid {
    grid-template-columns: 1fr;
  }

  .product-icon-bar {
    gap: 20px;
  }

  .quick-links {
    flex-direction: column;
    align-items: center;
  }

  .quick-link {
    width: 100%;
    max-width: 280px;
    text-align: center;
  }
}

