  .entertainment-grid {
    grid-template-columns: 1fr;
  }

  .product-icon-bar {
    gap: 20px;
  }

  .quick-links {
    flex-direction: column;
    align-items: center;
  }

  .quick-link {
    width: 100%;
    max-width: 280px;
    text-align: center;
  }
}

