cd /app/output && npx playwright test --reporter=list -x 2>/dev/null || node -e "
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();

  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', err => errors.push(err.message));

  const pages = ['index.html', 'store.html', 'shop-laptops.html', 'shop-tablets.html'];

  for (const p of pages) {
    errors.length = 0;
    console.log('Testing:', p);
    await page.goto('file:///app/output/' + p);
    await page.waitForTimeout(1000);
    if (errors.length > 0) {
      console.log('Errors in', p + ':', errors.join(', '));
    } else {
      console.log('✓', p, 'loaded without errors');
    }
  }

  await browser.close();
})();
"

